import React, { useState, useEffect, useCallback } from "react";
import "./styles/global.css";

import Nav from "./components/Nav";
import Hero from "./components/Hero";
import Marquee from "./components/Marquee";
import Collections from "./components/Collections";
import Shop from "./components/Shop";
import Craft from "./components/Craft";
import Process from "./components/Process";
import Testimonials from "./components/Testimonials";
import FAQ from "./components/FAQ";
import FinalCTA from "./components/FinalCTA";
import Footer from "./components/Footer";
import CartDrawer from "./components/CartDrawer";

import { COLORS, FONT_BODY, THEME_MODES, THEME_STORAGE_KEY } from "./constants/theme";

const getInitialThemeMode = () => {
  if (typeof window === "undefined") return THEME_MODES.LIGHT;

  const storedTheme = window.localStorage.getItem(THEME_STORAGE_KEY);
  if (storedTheme === THEME_MODES.LIGHT || storedTheme === THEME_MODES.DARK) {
    return storedTheme;
  }

  const mediaQuery =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-color-scheme: dark)")
      : null;

  return mediaQuery?.matches ? THEME_MODES.DARK : THEME_MODES.LIGHT;
};

export default function App() {
  const [themeMode, setThemeMode] = useState(getInitialThemeMode);
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [cartOpen, setCartOpen] = useState(false);
  const [cart, setCart] = useState([]);
  const [filter, setFilter] = useState("All");
  const [activeCollection, setActiveCollection] = useState("Rings");
  const [faqOpen, setFaqOpen] = useState(0);
  const [testimonialIdx, setTestimonialIdx] = useState(0);
  const [checkedOut, setCheckedOut] = useState(false);
  const [bump, setBump] = useState(false);
  const [emailSent, setEmailSent] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", themeMode);
    window.localStorage.setItem(THEME_STORAGE_KEY, themeMode);
  }, [themeMode]);

  const addToCart = useCallback((product) => {
    setCart((prev) => {
      const found = prev.find((i) => i.id === product.id);
      if (found) {
        return prev.map((i) => (i.id === product.id ? { ...i, qty: i.qty + 1 } : i));
      }
      return [...prev, { ...product, qty: 1 }];
    });
    setBump(true);
    setTimeout(() => setBump(false), 400);
  }, []);

  const updateQty = (id, delta) => {
    setCart((prev) =>
      prev
        .map((i) => (i.id === id ? { ...i, qty: Math.max(0, i.qty + delta) } : i))
        .filter((i) => i.qty > 0)
    );
  };

  const removeItem = (id) => setCart((prev) => prev.filter((i) => i.id !== id));

  const cartCount = cart.reduce((sum, i) => sum + i.qty, 0);
  const subtotal = cart.reduce((sum, i) => sum + i.qty * i.price, 0);

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const toggleTheme = useCallback(() => {
    setThemeMode((current) =>
      current === THEME_MODES.DARK ? THEME_MODES.LIGHT : THEME_MODES.DARK
    );
  }, []);

  return (
    <div
      style={{
        fontFamily: FONT_BODY,
        background: COLORS.surfaceBase,
        color: COLORS.text,
        position: "relative",
        minHeight: "100vh",
      }}
    >
      <div className="nyasa-root">
        <Nav
          scrolled={scrolled}
          menuOpen={menuOpen}
          setMenuOpen={setMenuOpen}
          cartOpen={cartOpen}
          setCartOpen={setCartOpen}
          cartCount={cartCount}
          bump={bump}
          scrollTo={scrollTo}
          setFilter={setFilter}
          themeMode={themeMode}
          toggleTheme={toggleTheme}
        />

        <Hero scrollTo={scrollTo} />

        <Marquee />

        <Collections
          activeCollection={activeCollection}
          setActiveCollection={setActiveCollection}
          setFilter={setFilter}
          scrollTo={scrollTo}
        />

        <Shop filter={filter} setFilter={setFilter} addToCart={addToCart} />

        <Craft />

        <Process />

        <Testimonials testimonialIdx={testimonialIdx} setTestimonialIdx={setTestimonialIdx} />

        <FAQ faqOpen={faqOpen} setFaqOpen={setFaqOpen} />

        <FinalCTA emailSent={emailSent} setEmailSent={setEmailSent} />

        <Footer setFilter={setFilter} scrollTo={scrollTo} />

        <CartDrawer
          cartOpen={cartOpen}
          setCartOpen={setCartOpen}
          cart={cart}
          checkedOut={checkedOut}
          setCheckedOut={setCheckedOut}
          updateQty={updateQty}
          removeItem={removeItem}
          subtotal={subtotal}
        />
      </div>
    </div>
  );
}
